import { createMemo, createSignal, For } from 'solid-js'

type Item = { id: number; name: string }

export function Search(props: { items: Item[] }) {
  const [query, setQuery] = createSignal('')
  const visible = createMemo(() =>
    props.items.filter((i) => i.name.toLowerCase().includes(query().toLowerCase())),
  )

  return (
    <div>
      <input value={query()} onInput={(e) => setQuery(e.currentTarget.value)} />
      <p>{visible().length} matches</p>
      <ul>
        <For each={visible()}>{(i) => <li>{i.name}</li>}</For>
      </ul>
    </div>
  )
}

