import { For } from '@pyreon/core'
import { computed, signal } from '@pyreon/reactivity'

type Item = { id: number; name: string }

export function Search(props: { items: Item[] }) {
  const query = signal('')
  const visible = computed(() =>
    props.items.filter((i) => i.name.toLowerCase().includes(query().toLowerCase())),
  )

  return (
    <div>
      <input value={query()} onInput={(e) => query.set(e.currentTarget.value)} />
      <p>{visible().length} matches</p>
      <ul>
        <For each={visible} by={(i) => i.id}>
          {(i) => <li>{i.name}</li>}
        </For>
      </ul>
    </div>
  )
}
